class Solution {
    public: int findTheCity(int n,vector<vector<int>>& edges,int distanceThreshold){
        const int INF=1000000000;
        vector<vector<int>> distance(n,vector<int>(n,INF));
        for(int i=0;i<n;++i)distance[i][i]=0;
        for(auto& edge:edges)distance[edge[0]][edge[1]]=distance[edge[1]][edge[0]]=min(distance[edge[0]][edge[1]],edge[2]);
        for(int k=0;k<n;++k)for(int i=0;i<n;++i)for(int j=0;j<n;++j)distance[i][j]=min(distance[i][j],distance[i][k]+distance[k][j]);
        int answer=-1,bestCount=INT_MAX;
        for(int city=0;city<n;++city){
            int count=0;
            for(int other=0;other<n;++other)count+=other!=city&&distance[city][other]<=distanceThreshold;
            if(count<=bestCount){
                bestCount=count;
                answer=city;
            }
        }
        return answer;
    }
};
